mapper.select:
SELECT A.vrfc_sn AS vrfcSn , A.std_se_cd AS stdSeCd , A.levl_seq AS levlSeq , A.vrfc_tbl_nm AS vrfcTblNm , A.vrfc_col_nm AS vrfcColNm , A.vrfc_rul_nm AS vrfcRulNm , A.rfrnc_nm AS rfrncNm , A.rfrnc_dtl_nm AS rfrncDtlNm , A.esntl_yn AS esntlYn , A.rfrnc_tbl_nm AS rfrncTblNm , A.fk_nm AS fkNm , A.rfrnc_col_nm AS rfrncColNm , A.std_trm_id AS stdTrmId , A.rul_aplcn_nm AS rulAplcnNm , A.unit_nm AS unitNm , A.scp_seq_nm AS scpSeqNm , A.prm_crtr_nm AS prmCrtrNm , A.vrbl_cn AS vrblCn , A.vrbl_dtl_cn AS vrblDtlCn , A.vrbl_rslt_cn AS vrblRsltCn , COALESCE(E.emp_nm, A.rgtr_id) AS rgtrId , TO_CHAR(A.reg_dt, 'YY.MM.DD') AS regDt FROM kids_own.tb_cm_m_vrfc A LEFT JOIN kids_own.tb_pp_m_mngr_info M ON M.emp_no = A.rgtr_id LEFT JOIN kids_own.tb_pp_m_emp_info E ON E.emp_no = M.emp_no WHERE 1=1
AND A.std_se_cd = #{stdSeCd}
AND A.vrfc_tbl_nm LIKE '%' || #{searchKeyword} || '%'
AND A.vrfc_col_nm LIKE '%' || #{searchKeyword} || '%'
ORDER BY A.vrfc_sn DESC LIMIT #{pageSize} OFFSET (#{page} - 1) * #{pageSize}

mapper.insert:

    SELECT nextval('kids_own.sq_cm_vrfc_sn')

INSERT INTO kids_own.tb_cm_m_vrfc (
       vrfc_sn
     , std_se_cd
     , levl_seq
     , vrfc_tbl_nm
     , vrfc_col_nm
     , vrfc_rul_nm
     , rfrnc_nm
     , rfrnc_dtl_nm
     , esntl_yn
     , rfrnc_tbl_nm
     , fk_nm
     , rfrnc_col_nm
     , std_trm_id
     , rul_aplcn_nm
     , unit_nm
     , scp_seq_nm
     , prm_crtr_nm
     , vrbl_cn
     , vrbl_dtl_cn
     , vrbl_rslt_cn
     , rgtr_id
     , reg_dt
     , mdfr_id
     , mdfcn_dt
) VALUES (
       #{vrfcSn}
     , #{stdSeCd}
     , #{levlSeq}
     , #{vrfcTblNm}
     , #{vrfcColNm}
     , #{vrfcRulNm}
     , #{rfrncNm}
     , #{rfrncDtlNm}
     , COALESCE(#{esntlYn}, 'N')
     , #{rfrncTblNm}
     , #{fkNm}
     , #{rfrncColNm}
     , #{stdTrmId}
     , #{rulAplcnNm}
     , #{unitNm}
     , #{scpSeqNm}
     , #{prmCrtrNm}
     , #{vrblCn}
     , #{vrblDtlCn}
     , #{vrblRsltCn}
     , COALESCE(#{rgtrId}, '관리자')
     , NOW()
     , COALESCE(#{mdfrId}, '관리자')
     , NOW()
)
